    document.addEventListener('DOMContentLoaded', () => { const card=document.querySelector('[data-danger-console]'), node=document.getElementById('danger-action-data'); if(!card||!node)return; let actions={}; try{actions=JSON.parse(node.textContent||'{}')}catch(e){return} const form=card.querySelector('[data-danger-form]'),select=card.querySelector('[data-danger-action]'),title=card.querySelector('[data-danger-title]'),description=card.querySelector('[data-danger-description]'),category=card.querySelector('[data-danger-category]'),count=card.querySelector('[data-danger-count]'),source=card.querySelector('[data-danger-source]'),button=card.querySelector('[data-purge-submit]'),password=card.querySelector('[data-danger-password]'),ack=card.querySelector('[data-purge-ack]'),phrase=card.querySelector('[data-danger-phrase]'),course=card.querySelector('[data-danger-course]'),courseValue=card.querySelector('[data-danger-course-value]'),scope=card.querySelector('[data-danger-scope]'),idField=card.querySelector('[data-danger-id]'),idWrap=card.querySelector('[data-danger-id-wrap]'),idValue=card.querySelector('[data-danger-id-value]'),base=card.dataset.baseUrl||''; const sync=()=>{button.disabled=password.value.trim()===''||!ack.checked}; const render=()=>{const item=actions[select.value]||actions[Object.keys(actions)[0]];form.action=base+item.action;category.textContent=item.category;title.textContent=item.title;description.textContent=item.description;count.textContent=String(item.count||0);phrase.value=item.phrase;source.href=base+item.source[0];source.innerHTML='Open '+item.source[1]+' <span aria-hidden="true">→</span>';scope.hidden=!item.scope;idWrap.hidden=!item.reset;if(!item.scope){course.value='0';courseValue.value='0'}if(!item.reset){idField.value='';idValue.value=''}button.textContent=item.button;sync()};select.addEventListener('change',render);course.addEventListener('change',()=>courseValue.value=course.value);idField.addEventListener('input',()=>idValue.value=idField.value);password.addEventListener('input',sync);ack.addEventListener('change',sync);form.addEventListener('submit',event=>{if(button.disabled){event.preventDefault();return}const item=actions[select.value];if(!window.confirm('Confirm: '+item.button+'? This action cannot be undone.'))event.preventDefault()});render(); });
